      "members_100" => struct.members_100,
      "members_25" => struct.members_25,
      "members_50" => struct.members_50,
      "members_75" => struct.members_75,
      "members_fte" => struct.members_fte,
      "name" => struct.name,
      "native_name" => struct.native_name,
      "networking" => struct.networking,
      "number_of_natural_persons" => struct.number_of_natural_persons,
      "other_code_of_conduct" => struct.other_code_of_conduct,
      "registration_date" => struct.registration_date,
      "status" => Status.encode(struct.status),
      "structure_members" => struct.structure_members,
      "sub_category" => struct.sub_category,
      "sub_category_title" => struct.sub_category_title,
      "updated_at" => struct.updated_at,
      "uri" => struct.uri,
      "web_site_url" => struct.web_site_url,
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule TopLevel do
  @enforce_keys [:count, :facets, :limit, :next, :offset, :previous, :results]
  defstruct [:count, :facets, :limit, :next, :offset, :previous, :results]

  @type t :: %__MODULE__{
          count: integer(),
          facets: Facets.t(),
          limit: integer(),
          next: String.t(),
          offset: integer(),
          previous: boolean(),
          results: [Result.t()]
        }

  def decode_count(value) when is_integer(value), do: value
  def decode_count(_), do: {:error, "Unexpected type when decoding TopLevel.count"}

  def encode_count(value) when is_integer(value), do: value
  def encode_count(_), do: {:error, "Unexpected type when encoding TopLevel.count"}

  def decode_limit(value) when is_integer(value), do: value
  def decode_limit(_), do: {:error, "Unexpected type when decoding TopLevel.limit"}

  def encode_limit(value) when is_integer(value), do: value
  def encode_limit(_), do: {:error, "Unexpected type when encoding TopLevel.limit"}

  def decode_next(value) when is_binary(value), do: value
  def decode_next(_), do: {:error, "Unexpected type when decoding TopLevel.next"}

  def encode_next(value) when is_binary(value), do: value
  def encode_next(_), do: {:error, "Unexpected type when encoding TopLevel.next"}

  def decode_offset(value) when is_integer(value), do: value
  def decode_offset(_), do: {:error, "Unexpected type when decoding TopLevel.offset"}

  def encode_offset(value) when is_integer(value), do: value
  def encode_offset(_), do: {:error, "Unexpected type when encoding TopLevel.offset"}

  def decode_previous(value) when is_boolean(value), do: value
  def decode_previous(_), do: {:error, "Unexpected type when decoding TopLevel.previous"}

  def encode_previous(value) when is_boolean(value), do: value
  def encode_previous(_), do: {:error, "Unexpected type when encoding TopLevel.previous"}

  def decode_results(value) when is_list(value), do: value
  def decode_results(_), do: {:error, "Unexpected type when decoding TopLevel.results"}

  def encode_results(value) when is_list(value), do: value
  def encode_results(_), do: {:error, "Unexpected type when encoding TopLevel.results"}

  def from_map(m) do
    %TopLevel{
      count: decode_count(m["count"]),
      facets: Facets.from_map(m["facets"]),
      limit: decode_limit(m["limit"]),
      next: decode_next(m["next"]),
      offset: decode_offset(m["offset"]),
      previous: decode_previous(m["previous"]),
      results: Enum.map(m["results"], &Result.from_map/1),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "count" => struct.count,
      "facets" => Facets.to_map(struct.facets),
      "limit" => struct.limit,
      "next" => struct.next,
      "offset" => struct.offset,
      "previous" => struct.previous,
      "results" => struct.results && Enum.map(struct.results, &Result.to_map/1),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
